3	// Chunks are collected as Buffers and decoded once at the end, rather than
4	// decoded per chunk: a multi-byte UTF-8 character can straddle a chunk
5	// boundary, and decoding the halves separately yields replacement characters.
6	const readStdin = async (): Promise<string> => {
7	  const chunks: Buffer[] = [];
8	
9	  for await (const chunk of process.stdin) chunks.push(chunk as Buffer);
10	
11	  return Buffer.concat(chunks).toString("utf8");
12	};
13	
14	const parseScenario = (json: string): Scenario => JSON.parse(json) as Scenario;
15	
16	// A refused scenario earns an explanation, not a stack trace: the office states
17	// its objection on stderr, writes no results, and returns a non-zero status.
18	try {
19	  const scenario = parseScenario(await readStdin());
20	
21	  process.stdout.write(JSON.stringify(runScenario(scenario)));
22	} catch (refusal) {
23	  process.stderr.write(`${(refusal as Error).message}\n`);
24	  process.exit(1);
25	}
