3	
4	// The CLI is exercised as a real subprocess rather than by importing it: exit
5	// codes and the stdout/stderr split are the contract, and only a process has
6	// those. This is why these tests live apart from claim-office.spec.ts.
7	const runCli = (stdin: string) =>
8	  spawnSync("npx", ["tsx", "src/cli.ts"], { input: stdin, encoding: "utf8" });
9	
10	describe("claim-office CLI", () => {
11	  it("writes {results: [...]} to stdout for a scenario read from stdin", () => {
12	    const scenario = {
