15	        {
16	          op: "quote",
17	          items: [
18	            { type: "amulet", material: "silver", enchantment: 2, cursed: false },
19	          ],
20	        },
21	        {
22	          op: "claim",
23	          policy: 0,
24	          incident: { cause: "fire", damages: [{ itemType: "amulet", amount: 200 }] },
