26	      ],
27	    };
28	
29	    const cli = runCli(JSON.stringify(scenario));
30	
31	    expect(cli.status).toBe(0);
32	    expect(JSON.parse(cli.stdout)).toEqual({
33	      results: [
34	        // 60 G base − 12 G loyalty + 6 G first insurance + 5 G fee
35	        { premium: 59 },
36	        // 200 G − 100 G deductible; cap 1200 G − 100 G
37	        { payout: 100, remainingCap: 1100 },
38	      ],
39	    });
40	  });
41	
42	  it("exits with a non-zero status and writes to stderr when the scenario is invalid", () => {
43	    const cli = runCli(
44	      JSON.stringify({
45	        customer: { yearsWithMHPCO: 0 },
46	        steps: [{ op: "quote", items: [{ type: "broomstick" }] }],
47	      }),
48	    );
49	
50	    expect(cli.status).not.toBe(0);
51	    expect(cli.stdout).toBe("");
52	    // The clerk explains the refusal; they do not hand over a stack trace.
53	    expect(cli.stderr).toMatch(/broomstick/);
54	    expect(cli.stderr).not.toMatch(/^\s+at /m);
55	  });
56	});
